# KINGSMEN JARVIS FULL COMMAND VOICE - NATIVE WINDOWS BRIDGE
$ErrorActionPreference="Continue"
param([string]$JarvisUrl="http://127.0.0.1:3000/api/jarvis/voice")
$RepoRoot=(Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path
$LogDir=Join-Path $RepoRoot "reports\jarvis\runtime"
$Log=Join-Path $LogDir "native-voice-bridge.log"
$ConversationUntil=(Get-Date).AddSeconds(-1)
$LastText=""
$LastAt=Get-Date
$Welcome="Welcome to Kingsmen Command, Commander. Jarvis is online. The command house is awake, your desk is prepared, and I stand ready to brief, inspect, report, search, repair, research, organise, or execute under Kingsmen doctrine."
New-Item -ItemType Directory -Force -Path $LogDir | Out-Null
function Write-JLog{param([string]$Text,[string]$Color="Cyan")$line="["+(Get-Date -Format "yyyy-MM-dd HH:mm:ss")+"] "+$Text;Add-Content -Path $Log -Value $line;Write-Host $line -ForegroundColor $Color}
function Speak-Jarvis{param([string]$Text)try{Add-Type -AssemblyName System.Speech -ErrorAction SilentlyContinue;$speaker=New-Object System.Speech.Synthesis.SpeechSynthesizer;$speaker.Volume=100;$speaker.Rate=-3;$voices=$speaker.GetInstalledVoices()|Where-Object{$_.Enabled -and $_.VoiceInfo.Culture.Name -like "en*"};if($voices.Count -gt 0){$speaker.SelectVoice($voices[0].VoiceInfo.Name)};[void]$speaker.Speak($Text);$speaker.Dispose()}catch{Write-JLog ("TTS ERROR: "+$_.Exception.Message) "Red"}}
function Send-ToJarvis{param([string]$Text,[double]$Confidence)try{$payload=@{text=$Text;confidence=$Confidence;source="windows-native-voice-bridge";timestamp=(Get-Date).ToString("o")}|ConvertTo-Json -Depth 5;$response=Invoke-RestMethod -Method Post -Uri $JarvisUrl -Body $payload -ContentType "application/json" -TimeoutSec 45;if($response.reply){Write-JLog ("JARVIS: "+$response.reply) "Green";Speak-Jarvis $response.reply}else{Write-JLog "Jarvis API returned no reply." "DarkYellow"}}catch{Write-JLog ("API POST ERROR: "+$_.Exception.Message) "Red";Speak-Jarvis "Commander, I heard the microphone bridge, but the Kingsmen Jarvis API did not answer. Confirm the web server is running, Sir."}}
function Process-Speech{param([string]$Text,[double]$Confidence)if([string]::IsNullOrWhiteSpace($Text)){return};if($Confidence -lt 0.15){Write-JLog ("LOW CONFIDENCE ["+[math]::Round($Confidence,2)+"]: "+$Text) "DarkYellow";return};$now=Get-Date;if($Text -eq $LastText -and (($now-$LastAt).TotalSeconds -lt 1.25)){return};Set-Variable -Name LastText -Scope Script -Value $Text;Set-Variable -Name LastAt -Scope Script -Value $now;$hasWake=$Text -match '\b(hey\s+)?jarvis\b';$inWindow=$now -lt $ConversationUntil;if($hasWake -or $inWindow){Set-Variable -Name ConversationUntil -Scope Script -Value $now.AddSeconds(90);Write-JLog ("HEARD ["+[math]::Round($Confidence,2)+"]: "+$Text) "Yellow";Send-ToJarvis -Text $Text -Confidence $Confidence}else{Write-JLog ("Heard but waiting for wake word: "+$Text) "DarkGray"}}
Clear-Host;Write-Host "===============================================================" -ForegroundColor Cyan;Write-Host " KINGSMEN JARVIS - FULL COMMAND VOICE BRIDGE" -ForegroundColor Cyan;Write-Host "===============================================================" -ForegroundColor Cyan;Write-Host "Keep this window open. Say: Jarvis" -ForegroundColor Yellow;Write-Host ""
try{Add-Type -AssemblyName System.Speech;Write-JLog "System.Speech loaded." "Green"}catch{Write-JLog ("System.Speech failed: "+$_.Exception.Message) "Red";Read-Host "Press Enter";exit 1}
Write-JLog "Speaking mandatory Kingsmen welcome." "Green";Speak-Jarvis $Welcome
while($true){try{$cultureList=@([System.Globalization.CultureInfo]::CurrentCulture.Name,"en-US","en-GB")|Select-Object -Unique;$rec=$null;foreach($cultureName in $cultureList){try{$culture=[System.Globalization.CultureInfo]::GetCultureInfo($cultureName);$rec=New-Object System.Speech.Recognition.SpeechRecognitionEngine($culture);$rec.SetInputToDefaultAudioDevice();Write-JLog ("Recognizer active with culture: "+$cultureName) "Green";break}catch{Write-JLog ("Recognizer failed for "+$cultureName+": "+$_.Exception.Message) "DarkYellow"}};if($null -eq $rec){$rec=New-Object System.Speech.Recognition.SpeechRecognitionEngine;$rec.SetInputToDefaultAudioDevice();Write-JLog "Recognizer active with default culture." "Green"};$choices=New-Object System.Speech.Recognition.Choices;foreach($phrase in @("Jarvis","Hey Jarvis","Good morning Jarvis","Good evening Jarvis","Jarvis give me a command brief","Jarvis inspect Kingsmen","Jarvis repair this","Jarvis what is your status","Jarvis debate this decision","Jarvis welcome me to Kingsmen Command")){[void]$choices.Add($phrase)};$gb=New-Object System.Speech.Recognition.GrammarBuilder;$gb.Append($choices);$wakeGrammar=New-Object System.Speech.Recognition.Grammar($gb);$dictation=New-Object System.Speech.Recognition.DictationGrammar;$rec.LoadGrammar($wakeGrammar);$rec.LoadGrammar($dictation);$rec.add_SpeechRecognized({param($sender,$eventArgs)try{Process-Speech -Text $eventArgs.Result.Text -Confidence $eventArgs.Result.Confidence}catch{Write-JLog ("HANDLER ERROR: "+$_.Exception.Message) "Red"}});$rec.add_SpeechRecognitionRejected({param($sender,$eventArgs)Write-JLog "Speech heard but Windows could not recognise it clearly." "DarkYellow"});$rec.RecognizeAsync([System.Speech.Recognition.RecognizeMode]::Multiple);Write-JLog "VOICE LISTENER ACTIVE. SAY: JARVIS" "Green";while($true){Start-Sleep -Seconds 2}}catch{Write-JLog ("VOICE ENGINE ERROR: "+$_.Exception.Message) "Red";Speak-Jarvis "Commander, the Windows voice engine failed. Check microphone permission and Windows speech language, Sir.";Start-Sleep -Seconds 5}}
